create or replace function public.sub4me_portfolio()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'contracts', coalesce((select jsonb_agg(jsonb_build_object(
      'id', c.id, 'product', c.product, 'scope', c.scope, 'start', to_char(c.start_date, 'YYYY-MM-DD'), 'end', to_char(c.end_date, 'YYYY-MM-DD'),
      'annualEur', c.annual_eur, 'status', c.status, 'noticeDays', c.notice_days, 'contractType', c.contract_type,
      'signedOn', to_char(c.signed_on, 'YYYY-MM-DD'), 'currency', c.currency, 'billingCycle', c.billing_cycle, 'paymentTerms', c.payment_terms,
      'poNumber', c.po_number, 'costCenter', c.cost_center, 'legalEntity', c.legal_entity, 'governingLaw', c.governing_law,
      'autoRenew', c.auto_renew, 'renewalTermMonths', c.renewal_term_months, 'priceUpliftCapPct', c.price_uplift_cap_pct,
      'discountPct', c.discount_pct, 'sapOwner', c.sap_owner, 'csm', c.csm, 'customerOwner', c.customer_owner, 'sla', c.sla,
      'dataCenter', c.data_center, 'deployment', c.deployment, 'licensedUnits', c.licensed_units, 'usedUnits', c.used_units,
      'unit', c.unit, 'invoicing', c.invoicing, 'termination', c.termination, 'notes', c.notes,
      'lines', coalesce((select jsonb_agg(jsonb_build_object('component', l.component, 'quantity', l.quantity, 'unit', l.unit, 'unitPriceEur', l.unit_price_eur, 'annualEur', l.annual_eur) order by l.position) from sub4me.contract_lines l where l.contract_id = c.id), '[]'::jsonb)) order by c.sort_order, c.id) from sub4me.contracts c), '[]'::jsonb),
    'offers', coalesce((select jsonb_agg(jsonb_build_object(
      'id', o.id, 'type', o.type, 'product', o.product, 'contractId', o.contract_id, 'scope', o.scope,
      'start', to_char(o.start_date, 'YYYY-MM-DD'), 'end', to_char(o.end_date, 'YYYY-MM-DD'), 'annualEur', o.annual_eur, 'currentAnnualEur', o.current_annual_eur,
      'validUntil', to_char(o.valid_until, 'YYYY-MM-DD'), 'status', o.status, 'createdOn', to_char(o.created_on, 'YYYY-MM-DD'), 'owner', o.owner, 'stage', o.stage,
      'probabilityPct', o.probability_pct, 'listPriceEur', o.list_price_eur, 'discountPct', o.discount_pct,
      'billingCycle', o.billing_cycle, 'paymentTerms', o.payment_terms, 'termMonths', o.term_months, 'autoRenew', o.auto_renew,
      'upliftCapPct', o.price_uplift_cap_pct, 'priceGuaranteeMonths', o.price_guarantee_months, 'approval', o.approval,
      'competitor', o.competitor, 'nextStep', o.next_step, 'conditions', o.conditions,
      'lines', coalesce((select jsonb_agg(jsonb_build_object('component', l.component, 'quantity', l.quantity, 'unit', l.unit, 'unitPriceEur', l.unit_price_eur, 'annualEur', l.annual_eur) order by l.position) from sub4me.offer_lines l where l.offer_id = o.id), '[]'::jsonb)) order by o.sort_order, o.id) from sub4me.offers o), '[]'::jsonb)
  );
$$;

revoke all on function public.sub4me_portfolio() from public, anon, authenticated;
grant execute on function public.sub4me_portfolio() to service_role;
